typedef struct s_Sensor_Status
{
	unsigned is_disabled    :1 ;
	unsigned is_bypassed    :1 ;
	unsigned warning_na     :1 ;
	unsigned trigger_na     :1 ;
	unsigned npc_warn_enable:1 ;
	unsigned npc_trg_enable :1 ;

}Sensor_Status ; 
	
//--------------------------------------------------------------------------//

typedef struct s_Sensor
{
  struct    s_Vrtc  vrtc_bypass;
  
  Npc       npc_warn           ;
  Npc       npc_trg            ;

  Sensor_Status    status      ;   

}*Sensor ;

